#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-06

# Gate: tests/coverage/hook-coverage-report.sh:131 (primary) and :277 (grep fallback)
# exit 0 iff overall line pct >= COVERAGE_THRESHOLD (default 70)
set -uo pipefail
H="${H:?set by the fault-arms runner}"
REPO="${REPO:?set by the fault-arms runner}"
G="$REPO/tests/coverage/hook-coverage-report.sh"
F="$H/fixtures/hook-coverage"; rm -rf "$F"; mkdir -p "$F/root/src/hooks/coverage"

# The script honors CLAUDE_PROJECT_DIR, so point it at a fixture root.
# Mirror only what it reads: src/hooks/src (+ __tests__) and src/hooks/coverage.
cp -R "$REPO/src/hooks/src" "$F/root/src/hooks/src"

run() { CLAUDE_PROJECT_DIR="$F/root" bash "$G" >"$F/out.$1.txt" 2>&1; echo $?; }

# control: coverage-summary.json present, total.lines.pct above threshold
cat > "$F/root/src/hooks/coverage/coverage-summary.json" <<'J'
{"total":{"lines":{"pct":88.4},"functions":{"pct":80},"branches":{"pct":75},"statements":{"pct":88}},
 "/x/src/pretool/a.ts":{"lines":{"total":10,"covered":9}}}
J
control_rc=$(run control)

# control2: same shape, below threshold
cat > "$F/root/src/hooks/coverage/coverage-summary.json" <<'J'
{"total":{"lines":{"pct":12.0},"functions":{"pct":10},"branches":{"pct":9},"statements":{"pct":12}}}
J
control2_rc=$(run control2)

# fault: coverage-summary.json MISSING -> silently falls back to grep heuristic
rm -f "$F/root/src/hooks/coverage/coverage-summary.json"
fault_rc=$(run fault)

# fault2: coverage-summary.json present but {}
echo '{}' > "$F/root/src/hooks/coverage/coverage-summary.json"
fault2_rc=$(run fault2)

# fault3: JSON missing AND the hooks source tree is empty (nothing to measure)
rm -f "$F/root/src/hooks/coverage/coverage-summary.json"
rm -rf "$F/root/src/hooks/src"; mkdir -p "$F/root/src/hooks/src"
fault3_rc=$(run fault3)

for a in control control2 fault fault2 fault3; do
  echo "--- $a:"; grep -aE "Source:|Coverage:|Line Coverage:|THRESHOLD|Total Hooks" "$F/out.$a.txt" | tail -5
done >&2

printf 'RESULT gate=%s control=%s control2=%s fault=%s fault2=%s fault3=%s\n' \
  hook-coverage-report "$control_rc" "$control2_rc" "$fault_rc" "$fault2_rc" "$fault3_rc"
